import{_ as t,o,c as i,a2 as n}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Documentation structure","description":"Scope, ownership, and publication rules for Sovereign documentation.","frontmatter":{"title":"Documentation structure","description":"Scope, ownership, and publication rules for Sovereign documentation.","docSection":"contributors","docType":"policy","audiences":["contributor"],"sourceUrl":"https://github.com/sovereignfs/sovereign/blob/main/docs/documentation-structure.md"},"headers":[],"relativePath":"documentation-structure.md","filePath":"documentation-structure.md"}'),s={name:"documentation-structure.md"};function a(d,e,r,c,l,p){return o(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="documentation-structure" tabindex="-1">Documentation structure <a class="header-anchor" href="#documentation-structure" aria-label="Permalink to &quot;Documentation structure&quot;">​</a></h1><p>Sovereign keeps product education, task-oriented guides, current technical reference, design decisions, and project operations separate. Each factual topic has one canonical owner; other pages summarize it and link to that owner.</p><h2 id="content-classes" tabindex="-1">Content classes <a class="header-anchor" href="#content-classes" aria-label="Permalink to &quot;Content classes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Purpose</th><th>Canonical location</th><th>Published</th></tr></thead><tbody><tr><td>Product</td><td>Explain Sovereign&#39;s value, capabilities, apps, and direction</td><td><code>product/</code>, <code>product-roadmap.md</code>, <code>instances.md</code></td><td>Yes</td></tr><tr><td>Get started</td><td>Short, sequential paths for users, operators, and app developers</td><td><code>get-started/</code></td><td>Yes</td></tr><tr><td>Audience hubs</td><td>Route each audience to canonical guides and references</td><td><code>guides/</code></td><td>Yes</td></tr><tr><td>Technical reference</td><td>Describe current behavior, configuration, APIs, and architecture</td><td>Named root references and <code>plugins/</code></td><td>Yes</td></tr><tr><td>Legal templates</td><td>Operator-fillable templates — privacy/terms extending the shipped root <code>PRIVACY.md</code>/<code>TOS.md</code>, plus a breach-response runbook</td><td><code>legal/</code></td><td>Yes</td></tr><tr><td>Research</td><td>Explore open-ended questions before a design is proposed</td><td><code>research/</code></td><td>No</td></tr><tr><td>Decisions</td><td>Record accepted and proposed cross-cutting designs</td><td><code>rfcs/</code></td><td>Yes, with status</td></tr><tr><td>Incidents</td><td>Record production incidents — timeline, root cause(s), resolution, follow-ups</td><td><code>incidents/</code></td><td>No</td></tr><tr><td>Workstreams</td><td>Sequence an accepted design&#39;s tasks across epics in dependency order</td><td><code>workstreams/</code></td><td>No</td></tr><tr><td>Project operations</td><td>Track tasks, plans, findings, and internal coordination</td><td><code>epics/</code>, <code>adhoc/</code> (being phased out — see below), roadmap and planning files</td><td>No</td></tr></tbody></table><h2 id="ownership-rules" tabindex="-1">Ownership rules <a class="header-anchor" href="#ownership-rules" aria-label="Permalink to &quot;Ownership rules&quot;">​</a></h2><ul><li><p>Product pages explain outcomes and avoid reproducing configuration or API reference material.</p></li><li><p>Get-started pages stop after the first successful path and link to the canonical reference for complete behavior.</p></li><li><p>Audience hubs are indexes. They should not become second copies of guides.</p></li><li><p>Technical references describe implemented behavior. Future designs belong in RFCs and must not be presented as shipped functionality.</p></li><li><p>RFCs explain decisions and proposals. They do not replace current reference documentation after implementation.</p></li><li><p>Research docs explore a question before it has a concrete design — findings, options, and a recommendation, not a commitment. A research doc precedes an RFC for open-ended topics; it is not deleted once an RFC lands, and not every research doc graduates to one (a documented &quot;not now&quot; is a valid outcome). See <code>docs/research/README.md</code>.</p></li><li><p><strong>Research-as-design (the RFC exception).</strong> A research doc may serve as the governing design directly, with no intermediate RFC, when it already contains a settled one. The test is whether an RFC would add a <em>decision</em> or only a <em>restatement</em>: if the options were weighed, the choice made, and the rejected alternatives recorded in the research doc, then an RFC repeating them adds a documentation trail and a review cycle without adding information. Permitted only when all four hold:</p><ol><li>The research doc records <strong>rejected alternatives with reasons</strong>, not just a recommendation — this is what an RFC&#39;s &quot;Alternatives considered&quot; would have carried, and it is what stops a decision being relitigated later.</li><li>Every <strong>genuinely open</strong> decision is an explicit gate in the workstream, not a silent gap. A design with unresolved forks is not settled and still needs an RFC.</li><li>A <strong>workstream</strong> carries the decisions forward in its &quot;Decisions locked&quot; table, and <strong>epic tasks</strong> carry the deliverables. The design is not left to be re-derived from prose.</li><li>The workstream and epic tasks <strong>cite the research doc where they would otherwise cite an RFC</strong>, so the governing document is unambiguous.</li></ol><p>Reference documentation is still updated on implementation, exactly as it would be after an RFC. This exception changes which document holds the design, not whether the design is written down. When in doubt, write the RFC — the exception exists for the case where the design is genuinely finished, not as a general shortcut.</p></li><li><p>Workstream docs sequence work; they do not design it or track its status. Design stays in <code>rfcs/</code>, full task specs stay in <code>epics/</code>, and status stays in <code>ROADMAP.md</code> rows and epic headings. A workstream adds dependency order across epics, the decisions already locked (so they are not reopened mid-execution), and the gates that determine whether later work proceeds. It is normally written after its governing RFCs — if a design is not settled enough to sequence, the missing step is an RFC or research doc. Under the research-as-design exception above, a workstream may instead be governed by a research doc directly. See <code>docs/workstreams/README.md</code>.</p></li><li><p>The public product roadmap describes themes. <code>ROADMAP.md</code> and <code>epics/</code> remain the private engineering queue and source of task status.</p></li><li><p>Incident docs are a factual record of what happened during a specific production incident — timeline, root cause(s), the exact remediation run against production, and follow-up actions with status. One file per incident, named <code>docs/incidents/YYYY-MM-DD-short-slug.md</code>. They are not the place to propose new designs (that&#39;s an RFC or research doc, linked from the incident&#39;s follow-ups) and are never edited to reflect later changes — if a follow-up itself needs documenting, it gets its own entry in whatever reference doc it changes, cross-linked back to the incident, not folded into the incident file after the fact.</p></li><li><p><code>docs/adhoc/</code> predates the <code>incidents/</code> and <code>research/</code> classes and mixed both purposes (bug write-ups, findings, plans) without a clear boundary. It is being phased out: new incident write-ups go in <code>incidents/</code>, new open-ended findings/plans go in <code>research/</code> or a package/app-local doc as appropriate, and existing <code>adhoc/</code> content stays where it is until someone deliberately migrates or retires it — don&#39;t add new files there.</p></li><li><p><code>docs/public/</code> is not a content class — it is the docs site&#39;s static-asset directory (favicons, the social-preview image, per-plugin icon SVGs used on product pages), copied verbatim into the built site the way any VitePress <code>public/</code> directory is. It carries no documentation prose, so it has no row in the table above and no ownership rule beyond this one.</p></li></ul><h2 id="technical-reference-metadata" tabindex="-1">Technical-reference metadata <a class="header-anchor" href="#technical-reference-metadata" aria-label="Permalink to &quot;Technical-reference metadata&quot;">​</a></h2><p>Canonical root references keep stable filenames and URLs while declaring their ownership in frontmatter:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">docSection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">operators</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">docType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">guide</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">audiences</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">operator</span></span></code></pre></div><p><code>docSection</code> controls the primary navigation group and must be one of <code>operators</code>, <code>app-developers</code>, <code>architecture-security</code>, or <code>contributors</code>. <code>docType</code> describes how the page should be maintained and must be <code>guide</code>, <code>reference</code>, or <code>policy</code>. <code>audiences</code> records every audience expected to use the page and may contain <code>user</code>, <code>operator</code>, <code>app-developer</code>, or <code>contributor</code>.</p><p>A page has one primary section even when several audiences use it. For example, <code>security.md</code> belongs to Architecture &amp; Security while serving all four audiences. Metadata expresses ownership without moving established files or changing their public and GitHub URLs.</p><h2 id="publication-boundary" tabindex="-1">Publication boundary <a class="header-anchor" href="#publication-boundary" aria-label="Permalink to &quot;Publication boundary&quot;">​</a></h2><p>The docs site (built from the <code>sovereignfs/sovereignfs</code> workbench repo, not this one) uses the explicit allowlist policy in that repo&#39;s <code>docs/docs-sync.manifest.json</code>. Public directories and canonical root references are opted in there via a build-time sparse-checkout of this repo; every other Markdown file here is never fetched, so it can&#39;t appear on the site.</p><p>Adding a link to navigation does not make a document public. A new public content class or root reference requires a deliberate change to that manifest, which keeps internal notes from becoming public merely because they live under <code>docs/</code>.</p><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><p>Long-standing root references such as <code>self-hosting.md</code>, <code>plugin-development.md</code>, and <code>architecture.md</code> keep their source paths and URLs. Repository tests, source comments, RFCs, package documentation, and external GitHub links depend on those locations. Their audience ownership is expressed through navigation and this contract rather than disruptive file moves.</p><p>Audience indexes live in <code>guides/</code>, while explicit VitePress rewrites preserve their established <code>/docs/</code> public URLs. Source organization can therefore stay clear without invalidating bookmarks, search results, or inbound links.</p>`,17)])])}const m=t(s,[["render",a]]);export{u as __pageData,m as default};
